// Two variable definitions
const molIndex = OLI.random(0,5);
const molArray = [2.0,2.5,3.0,3.5,4.0,4.5,5.0];
const mol = molArray[molIndex] .toFixed(2);
const volIndex = OLI.random(0,5);
const volArray = [5.5,6.0,6.5,7.0,7.5,8.0,8.5,9.0,9.5];
const vol = volArray[volIndex] .toFixed(2);
const cor1NoRound = (mol/vol);
const correct1 = (mol/vol)
const correct1sf = correct1 .toPrecision(3);
const cor1Low = (correct1*0.98);
const cor1High = (correct1*1.02);
const cor1Sq = (cor1NoRound*cor1NoRound);
const step2_1 = (cor1Sq*0.0000000038);
const step2 = step2_1/4;
const correct2 = Math.cbrt(step2) 
const correct2sf = correct2 .toPrecision(2);
const cor2Low = (correct2*0.98);
const cor2High = (correct2*1.02);
const correct3 = (2*correct2) 
const correct3sf = correct3 .toPrecision(2);
const cor3Low = (correct3*0.95);
const cor3High = (correct3*1.05);
// Expose variables to OLI
module.exports = {
 mol,
  vol,
  cor1NoRound,
  correct1,
  correct1sf,
  cor1Low,
  cor1High,
  cor1Sq,
  step2,
  correct2,
  correct2sf,
  cor2Low,
  cor2High,
  correct3,
  correct3sf,
  cor3Low,
  cor3High
};
